import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicLong;
public final class OrderService {
  private final Map<String, Reservation> reservations = new ConcurrentHashMap<>();
  private final AtomicLong sequence = new AtomicLong();
  public Reservation reserve(String orderId, int amount) {
    Reservation created = reservations.computeIfAbsent(orderId, id -> {
      Reservation r = new Reservation(id, amount, sequence.incrementAndGet());
      Thread.yield();
      return r;
    });
    return created;
  }
  public int size() { return reservations.size(); }
}
```

